def _new_code(Registration):
    while True:
        code = 'EVT' + ''.join(
            secrets.choice('ABCDEFGHJKLMNPQRSTUVWXYZ23456789') for _ in range(8)
        )
        if not Registration.objects.filter(code=code).exists():
            return code


